import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract opponent moves for quick analysis
    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    last_me, last_opp = history[-1]

    # --- Opening: cooperate, but punish an immediate defection ---
    if n < 3:
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        return 'C'

    # Count totals
    opp_def = 0
    opp_coop = 0
    my_def = 0
    my_coop = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for a, b in history:
        if a == 'C':
            my_coop += 1
        else:
            my_def += 1
        if b == 'C':
            opp_coop += 1
        else:
            opp_def += 1
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'C' and b == 'D':
            cd += 1
        elif a == 'D' and b == 'C':
            dc += 1
        else:
            dd += 1

    coop_rate = opp_coop / float(n)
    defect_rate = opp_def / float(n)

    # Recent window statistics
    window = 8 if n >= 8 else n
    rec = opp[-window:]
    rec_def = 0
    for x in rec:
        if x == 'D':
            rec_def += 1
    rec_coop = window - rec_def

    # Consecutive opponent defections at the tail
    cons_opp_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            cons_opp_def += 1
        else:
            break

    # Consecutive opponent cooperations at the tail
    cons_opp_coop = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            cons_opp_coop += 1
        else:
            break

    # Detect pure/near-pure defector: defect to minimize losses
    if n >= 6 and opp_def >= n - 1:
        return 'D'
    if n >= 12 and defect_rate >= 0.85 and rec_def >= window - 1:
        return 'D'
    if n >= 20 and defect_rate >= 0.7 and rec_def * 2 >= window:
        return 'D'

    # Detect persistently non-cooperative: after enough data, lock to D
    if n >= 15 and opp_coop <= 1 and dc >= 3:
        return 'D'

    # If opponent just defected:
    if last_opp == 'D':
        # If we caused it by defecting, offer cooperation to recover quickly
        if last_me == 'D' and cons_opp_def <= 2:
            # Check if this looks like retaliation for our defection
            if n >= 2 and history[-2][0] == 'D':
                # We've been defecting; try to restore mutual C
                if coop_rate >= 0.4:
                    return 'C'
            if coop_rate >= 0.5:
                return 'C'
            return 'D'
        # If opponent defected unprovoked (we cooperated last round)
        if last_me == 'C':
            # One-step retaliation, then forgive if they have good history
            if cons_opp_def == 1:
                if coop_rate >= 0.5:
                    return 'D'
                return 'D'
            # Opponent defecting repeatedly
            if cons_opp_def >= 3:
                if coop_rate >= 0.4 and rng.random() < 0.15:
                    return 'C'
                return 'D'
            if coop_rate >= 0.6 and rng.random() < 0.3:
                return 'C'
            return 'D'
        # Both defecting; occasionally try to break the cycle
        if cons_opp_def >= 2:
            if coop_rate >= 0.35 and rng.random() < 0.2:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated
    # If we defected and they cooperated, reward them by cooperating
    if last_me == 'D':
        return 'C'

    # Opponent cooperating consistently
    # Check for signs they might exploit: if they've defected a lot overall
    if defect_rate >= 0.35 and rec_def >= 2:
        # Cautious: defect opportunistically
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # Mostly cooperative opponent
    if coop_rate >= 0.6 or rec_coop >= window - 1:
        # Rare probe to test for exploitable passivity, but only in safe phases
        if n >= 30 and n < 95 and coop_rate >= 0.75 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Moderate defection rate: reciprocate with slight forgiveness
    if rec_def >= 3:
        return 'D'
    if rec_def >= 2:
        if rng.random() < 0.4:
            return 'C'
        return 'D'

    # Default cooperate
    return 'C'
